<?php
require __DIR__.'/includes/bootstrap.php';$user=require_user(true);require __DIR__.'/includes/modules.php';require __DIR__.'/includes/layout.php';
$page=max(1,(int)($_GET['page']??1));$entity=is_string($_GET['entity']??null)?substr($_GET['entity'],0,40):'';$where=$entity!==''?' WHERE a.entity_type=?':'';
$rows=query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN admin_users u ON u.id=a.admin_user_id'.$where.' ORDER BY a.id DESC LIMIT 50 OFFSET '.(($page-1)*50),$entity!==''?[$entity]:[])->fetchAll();
page_header('Audit history',$user);echo '<p class="muted">Actions and record references only. Passwords, tokens and form contents are not recorded here.</p><form method="get" class="filters">';input_field('entity','Entity filter',$entity);echo '<button>Filter</button></form><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>UTC time</th><th>Staff</th><th>Action</th><th>Entity</th><th>Record</th></tr></thead><tbody>';
foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['full_name']??'Website / system').'</td><td>'.e($r['action']).'</td><td>'.e($r['entity_type']).'</td><td>'.e($r['entity_id']).'</td></tr>';echo '</tbody></table></div><nav class="pagination">';if($page>1)echo '<a href="?'.e(http_build_query(['page'=>$page-1,'entity'=>$entity])).'">Previous</a>';if(count($rows)===50)echo '<a href="?'.e(http_build_query(['page'=>$page+1,'entity'=>$entity])).'">Next</a>';echo '</nav>';page_footer();
